import React, { useState, useEffect } from 'react';
import { Routes, Route, NavLink, useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
    LayoutDashboard, Package, TrendingUp, DollarSign,
    Menu, X, Bell, Moon, Sun, LogOut, User,
    ShoppingCart, BarChart3
} from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { useAuth } from '../../context/AuthContext';
import Overview from './Overview';
import OrdersQueue from './OrdersQueue';
import MyOrders from './MyOrders';
import Earnings from './Earnings';

const navigation = [
    { path: '/sales-rep/dashboard', icon: LayoutDashboard, label: 'Overview', end: true },
    { path: '/sales-rep/dashboard/queue', icon: ShoppingCart, label: 'Orders Queue' },
    { path: '/sales-rep/dashboard/my-orders', icon: Package, label: 'My Orders' },
    { path: '/sales-rep/dashboard/earnings', icon: DollarSign, label: 'Earnings' },
];

const SalesRepDashboard = () => {
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const { isDark, toggleTheme } = useTheme();
    const { user, logout } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();

    useEffect(() => { setSidebarOpen(false); }, [location.pathname]);

    const handleLogout = () => { logout(); navigate('/login'); };

    const getPageTitle = () => {
        for (const item of navigation) {
            if (location.pathname === item.path || (item.end && location.pathname === '/sales-rep/dashboard')) {
                return item.label;
            }
        }
        return 'Dashboard';
    };

    return (
        <div className="min-h-screen bg-surface-light dark:bg-surface-dark">
            <AnimatePresence>
                {sidebarOpen && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setSidebarOpen(false)} />
                )}
            </AnimatePresence>

            <aside className={`fixed top-0 left-0 z-50 h-full w-64 bg-white dark:bg-brand-950 border-r border-slate-200 dark:border-brand-800 shadow-xl transition-transform duration-300 flex flex-col
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 lg:static lg:z-auto`}>
                <div className="flex items-center justify-between p-4 border-b border-slate-200 dark:border-brand-800">
                    <div className="flex items-center gap-2">
                        <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-gold-400 to-gold-600 flex items-center justify-center shadow-lg shadow-gold-500/25">
                            <Package className="h-5 w-5 text-white" />
                        </div>
                        <div>
                            <h1 className="font-extrabold text-brand-800 dark:text-white text-lg">SalesPro</h1>
                            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-semibold">Sales Rep</p>
                        </div>
                    </div>
                    <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-1.5 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-lg">
                        <X className="h-5 w-5 text-slate-500" />
                    </button>
                </div>

                <nav className="flex-1 overflow-y-auto py-4 px-3 space-y-1">
                    {navigation.map((item) => (
                        <NavLink key={item.path} to={item.path} end={item.end}
                            className={({ isActive }) => `
                flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all duration-200 text-sm font-medium
                ${isActive ? 'bg-gold-50 text-gold-700 dark:bg-gold-900/20 dark:text-gold-400 shadow-sm' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-brand-800/30'}
              `}>
                            <item.icon className="h-5 w-5" />
                            {item.label}
                        </NavLink>
                    ))}
                </nav>

                <div className="p-3 border-t border-slate-200 dark:border-brand-800">
                    <div className="flex items-center gap-3">
                        <div className="h-9 w-9 rounded-full bg-gradient-to-br from-gold-400 to-gold-600 flex items-center justify-center shadow-md">
                            <span className="text-white text-sm font-bold">{user?.firstName?.[0]}{user?.lastName?.[0]}</span>
                        </div>
                        <div className="flex-1 min-w-0">
                            <p className="text-sm font-semibold text-brand-800 dark:text-white truncate">{user?.firstName} {user?.lastName}</p>
                            <p className="text-xs text-slate-500 truncate">{user?.email}</p>
                        </div>
                        <button onClick={handleLogout} className="p-1.5 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-lg" title="Sign Out">
                            <LogOut className="h-4 w-4 text-slate-400 hover:text-rose-500 transition-colors" />
                        </button>
                    </div>
                </div>
            </aside>

            <div className="lg:pl-64">
                <header className="sticky top-0 z-30 glass-effect border-b border-slate-200 dark:border-brand-800">
                    <div className="flex items-center justify-between px-4 lg:px-6 h-16">
                        <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-xl">
                            <Menu className="h-5 w-5 text-slate-600" />
                        </button>
                        <h2 className="text-lg font-bold text-brand-800 dark:text-white">{getPageTitle()}</h2>
                        <div className="flex items-center gap-2">
                            <button className="relative p-2 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-xl">
                                <Bell className="h-5 w-5 text-slate-500" />
                                <span className="absolute top-1.5 right-1.5 h-2 w-2 bg-rose-500 rounded-full" />
                            </button>
                            <button onClick={toggleTheme} className="p-2 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-xl">
                                {isDark ? <Sun className="h-5 w-5 text-gold-500" /> : <Moon className="h-5 w-5 text-brand-600" />}
                            </button>
                        </div>
                    </div>
                </header>

                <main className="p-4 lg:p-6">
                    <AnimatePresence mode="wait">
                        <motion.div key={location.pathname} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.15 }}>
                            <Routes>
                                <Route index element={<Overview />} />
                                <Route path="queue" element={<OrdersQueue />} />
                                <Route path="my-orders" element={<MyOrders />} />
                                <Route path="earnings" element={<Earnings />} />
                            </Routes>
                        </motion.div>
                    </AnimatePresence>
                </main>
            </div>
        </div>
    );
};

export default SalesRepDashboard;
